# Panel buffer: {{WIDTH}}x{{HEIGHT}} (native portrait), 1 bit/pixel, MSB first, 1 = white.
# Do not edit the bitmap by hand; re-run img2code.py with a new image instead.
import time
import board
import busio
import digitalio
from ssd1680 import SSD1680, WIDTH, HEIGHT

# Packed bitmap in the panel's native orientation (rows of WIDTH/8 bytes, HEIGHT rows).
DATA = bytes.fromhex(
{{DATA}}
)

# NFC tag content (CC + NDEF message), generated from the selected JSON profile.
# None = the selected NFC profile was not present when this file was generated.
NFC_DATA = {{NFC_DATA}}
NFC_MODE = "{{NFC_MODE}}"


def nfc_unlock_buttons_held_at_boot():
    held = []
    for pin, label in ((board.GP5, "A/GP5"), (board.GP4, "B/GP4")):
        button = digitalio.DigitalInOut(pin)
        try:
            button.direction = digitalio.Direction.INPUT
            button.pull = digitalio.Pull.UP
            if not button.value:
                held.append(label)
        finally:
            button.deinit()
    return held


NFC_UNLOCK_REQUIRED = {{NFC_UNLOCK_REQUIRED}}
NFC_HELD_BUTTONS = nfc_unlock_buttons_held_at_boot() if NFC_UNLOCK_REQUIRED else []
NFC_BUTTON_A_UPDATE = NFC_UNLOCK_REQUIRED and "A/GP5" in NFC_HELD_BUTTONS
NFC_BUTTON_B_BOOT_UNLOCK = NFC_UNLOCK_REQUIRED and "B/GP4" in NFC_HELD_BUTTONS
NFC_WRITE_ENABLED = not NFC_UNLOCK_REQUIRED or NFC_BUTTON_A_UPDATE or NFC_BUTTON_B_BOOT_UNLOCK
NFC_RELOCK_AFTER_UPDATE = NFC_BUTTON_A_UPDATE and not NFC_BUTTON_B_BOOT_UNLOCK
NFC_ADDR = 0x53
NFC_SYSTEM_ADDR = 0x57
NFC_RF_AREA_1_SECURITY = 0x0004
NFC_I2C_PASSWORD = b"\x00" * 8


def nfc_read_register(i2c, address, register, size=1):
    value = bytearray(size)
    i2c.writeto_then_readfrom(address, register.to_bytes(2, "big"), value)
    return value


def configure_nfc_rf_write_protection(writable):
    i2c = busio.I2C(scl=board.GP11, sda=board.GP10, frequency=100_000)
    try:
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
            print("NFC: I2C scan:", ["0x%02X" % address for address in devices])
            if NFC_SYSTEM_ADDR not in devices:
                print("NFC: system address 0x%02X missing" % NFC_SYSTEM_ADDR)
                return False

            password_message = NFC_I2C_PASSWORD + b"\x09" + NFC_I2C_PASSWORD
            i2c.writeto(NFC_SYSTEM_ADDR, b"\x09\x00" + password_message)
            time.sleep(0.01)
            session = nfc_read_register(i2c, NFC_ADDR, 0x2004)[0]
            print("NFC: I2C password session %s" % ("open" if session & 0x01 else "closed"))
            if not session & 0x01:
                raise RuntimeError("ST25DV I2C password rejected; RF protection unchanged")

            current = nfc_read_register(i2c, NFC_SYSTEM_ADDR, NFC_RF_AREA_1_SECURITY)[0]
            protection = 0 if writable else 1
            updated = (current & 0xF3) | (protection << 2)
            print("NFC: RFA1SS before=0x%02X RF-write-protected=%s target=%s" % (
                current, bool(current & 0x0C), "writable" if writable else "protected"))
            if updated != current:
                i2c.writeto(NFC_SYSTEM_ADDR, b"\x00\x04" + bytes((updated,)))
                time.sleep(0.01)

            verified = nfc_read_register(i2c, NFC_SYSTEM_ADDR, NFC_RF_AREA_1_SECURITY)[0]
            print("NFC: RFA1SS after=0x%02X RF-write-protected=%s" % (verified, bool(verified & 0x0C)))
            if (verified & 0x0C) != (protection << 2):
                raise RuntimeError("ST25DV RF protection setting did not verify")
            return True
        finally:
            i2c.unlock()
    finally:
        i2c.deinit()


NFC_SECURITY_READY = False
try:
    NFC_SECURITY_READY = configure_nfc_rf_write_protection(NFC_WRITE_ENABLED)
    if NFC_SECURITY_READY:
        print("NFC: RF writes %s" % ("enabled" if NFC_WRITE_ENABLED else "locked"))
except Exception as e:
    print("NFC: RF protection setup failed:", e)

assert (WIDTH, HEIGHT) == ({{WIDTH}}, {{HEIGHT}}), "panel size differs from the generated bitmap"
assert len(DATA) == (WIDTH // 8) * HEIGHT, "bitmap size mismatch"

# ---------------------------------------------------------------------------
# NFC: ST25DV04K dynamic tag on I2C (SDA=GP10, SCL=GP11). The tag's user memory
# (I2C address 0x53, 16-bit memory address) is what phones read over RF.
# Only blocks that differ are rewritten, so a normal boot writes nothing.
def publish_nfc(data):
    data = bytes(data) + b"\x00" * (-len(data) % 4)  # tag memory is 4-byte blocks
    print("NFC: profile=%s target-length=%d bytes" % (NFC_MODE, len(data)))
    i2c = busio.I2C(scl=board.GP11, sda=board.GP10, frequency=100_000)
    try:
        while not i2c.try_lock():
            pass
        try:
            if NFC_ADDR not in i2c.scan():
                print("NFC: tag not found at 0x%02X" % NFC_ADDR)
                return
            cur = bytearray(len(data))
            i2c.writeto_then_readfrom(NFC_ADDR, b"\x00\x00", cur)
            changed_offsets = [off for off in range(0, len(data), 4)
                               if cur[off:off + 4] != data[off:off + 4]]
            print("NFC: current data read=%d bytes; changed blocks=%d offsets=%s" % (
                len(cur), len(changed_offsets), changed_offsets))
            written = 0
            for off in range(0, len(data), 4):
                if cur[off:off + 4] == data[off:off + 4]:
                    continue
                start = time.monotonic()
                retries = 0
                while True:  # the tag NACKs while it is busy storing the previous block
                    try:
                        i2c.writeto(NFC_ADDR, bytes((off >> 8, off & 0xFF)) + data[off:off + 4])
                        break
                    except OSError:
                        if time.monotonic() - start > 1.0:
                            raise
                        retries += 1
                        time.sleep(0.005)
                if retries:
                    print("NFC: block 0x%04X needed %d busy retries" % (off, retries))
                written += 1
            readback = bytearray(len(data))
            i2c.writeto_then_readfrom(NFC_ADDR, b"\x00\x00", readback)
            mismatches = [offset for offset in range(len(data))
                          if readback[offset] != data[offset]]
            if mismatches:
                print("NFC: read-back FAILED; mismatch count=%d offsets=%s" % (
                    len(mismatches), mismatches[:16]))
                raise RuntimeError("NFC memory does not match generated payload")
            print("NFC: read-back verified; %d bytes, %d blocks written" % (len(data), written))
        finally:
            i2c.unlock()
    finally:
        i2c.deinit()


if NFC_DATA is not None:
    print("NFC: profile=%s; GP5-update=%s; GP4-unlock-for-boot=%s; buttons-held=%s" % (
        NFC_MODE, NFC_BUTTON_A_UPDATE, NFC_BUTTON_B_BOOT_UNLOCK, NFC_HELD_BUTTONS or "none"))
    if not NFC_SECURITY_READY:
        print("NFC: payload update skipped because RF protection was not configured")
    elif NFC_UNLOCK_REQUIRED and not NFC_WRITE_ENABLED:
        print("NFC: payload unchanged; hold GP5 to update once or GP4 to unlock for this boot")
    else:
        if NFC_BUTTON_A_UPDATE and not NFC_BUTTON_B_BOOT_UNLOCK:
            print("NFC: GP5 one-shot update; RF protection will be restored afterward")
        elif NFC_BUTTON_B_BOOT_UNLOCK:
            print("NFC: GP4 boot unlock; RF writes remain enabled until restart")
        try:
            publish_nfc(NFC_DATA)
        except Exception as e:  # never let NFC problems affect the display
            print("NFC failed:", e)
        finally:
            if NFC_RELOCK_AFTER_UPDATE:
                try:
                    print("NFC: restoring RF write protection after GP5 update")
                    if not configure_nfc_rf_write_protection(False):
                        raise RuntimeError("tag missing while restoring RF write protection")
                    print("NFC: RF writes locked after update")
                except Exception as e:
                    print("NFC: failed to restore RF write protection:", e)


# Refresh only after NFC update and any GP5 relock attempt have completed.
spi = busio.SPI(clock=board.GP14, MOSI=board.GP15)
epd = SSD1680(spi, board.GP13, board.GP17, board.GP18, board.GP16, baudrate=20_000_000)
epd.timeout = 3.0

print("init ok:", epd.init())   # init() also restores the factory waveform (OTP LUT)
epd.display_full(bytearray(DATA))  # full refresh; the driver powers the panel down itself
print("done")
